/**
 * Build POST /s-api/openapi/currentvalue/list from netList + global.config
 *
 * Purpose:
 *   - Read connection settings (host, port, scheme) from global.config
 *   - Read all points for the current controller from:
 *       global.netList.larmia_controller[host].points
 *   - Build a PIDList for /currentvalue/list
 *   - Attach the original items to msg.items
 *   - Configure msg for an HTTP POST request
 */

const STORE = "persistent";

// 1) Read config (host, port, scheme)
const cfg = global.get("config", STORE) || {};
const scheme = cfg.scheme || "http";
const ip = cfg.host;
const port = cfg.port || "";

// Validate host
if (!ip) {
  node.error("Missing cfg.host in global.config (controller host/IP).");
  return null;
}

// 2) Read points from netList.larmia_controller[ip].points
let inv = global.get("netList", STORE) || {};
inv.larmia_controller ??= {};
const controller = inv.larmia_controller[ip];

if (!controller || !controller.points) {
  node.warn(`No controller.points found under netList.larmia_controller["${ip}"]. Run the points flow first.`);
  return null;
}

const points = controller.points || {};

// Convert object -> array and keep only points with toStream === true
const items = Object.keys(points)
  .map(pid => points[pid])
  .filter(p => p && p.toStream === true);

if (!items.length) {
  node.warn(`No points with toStream=true found in netList.larmia_controller["${ip}"].points. Check configuration or run the points flow first.`);
  return null;
}

// 3) Build PIDList (unique PIDs as strings)
const pidList = [...new Set(
  items
    .map(o => {
      if (!o) return "";
      if (o.PID !== undefined && o.PID !== null) return String(o.PID);
      return "";
    })
    .filter(Boolean)
)];

if (!pidList.length) {
  node.warn(`No PID values found in netList points for "${ip}" (with toStream=true).`);
  return null;
}

// 4) Read token from larmiaAuth (same structure as in gettoken flow)
const auth = global.get("larmiaAuth", STORE) || {};
const token = auth?.tokens?.[ip];

if (!token) {
  node.error(`Missing token for "${ip}" in global.larmiaAuth.tokens – run the gettoken flow first.`);
  return null;
}

// 5) Attach items & metadata, build HTTP request
msg.items = items;
msg.job_uuid = cfg.JOB_UUID;

// Build URL (assume port already contains any leading colon if needed)
msg.method = "POST";
msg.url = `${scheme}://${ip}/s-api/openapi/currentvalue/list`;

msg.headers = {
  Accept: "application/json",
  "Content-Type": "application/json",
  Authorization: `Bearer ${token}`
};

msg.payload = { PIDList: pidList };
msg.rejectUnauthorized = false;

return msg;

/**
 * Merge values back into netList and build a telemetry message.
 *
 * Input:
 *   - msg.items: original list of point objects (from netList)
 *   - msg.payload.ValueList: response from /currentvalue/list
 *
 * Side effects:
 *   - Updates global.netList.larmia_controller[ip].points[PID] with:
 *       latestRead
 *       hasValue
 *
 * Output:
 *   - msg.payload: telemetry envelope:
 *       {
 *         messageType: "telemetry",
 *         source: "larmia",
 *         ip,
 *         job_uuid,
 *         items: [ { ip, pid, label, dataType, value, unit?, latestRead } ]
 *       }
 */

const STORE = "persistent";
const cfg = global.get("config", STORE) || {};

const ip = cfg.host;
const jobUuid = cfg.JOB_UUID;

// 1) Original list (from previous node)
let items = Array.isArray(msg.items) ? msg.items : [];

// 2) Rows from response: payload.ValueList
const rows = Array.isArray(msg.payload?.ValueList) ? msg.payload.ValueList : [];

// 3) Build lookup: PID -> { latestRead, value }
const byPID = {};
for (const r of rows) {
  if (!r) continue;
  const pidStr =
    r.PID !== undefined && r.PID !== null ? String(r.PID) : "";
  if (!pidStr) continue;

  byPID[pidStr] = {
    latestRead: r.Time ?? null,
    value: Object.prototype.hasOwnProperty.call(r, "Value") ? r.Value : null
  };
}

// 4) Read netList for this IP and update points with latestRead / hasValue
let inv = global.get("netList", STORE) || {};
inv.larmia_controller ??= {};
const controller = inv.larmia_controller[ip] || {};
const points = controller.points || {};

// Update both the items array and points object
for (const it of items) {
  if (!it) continue;
  const pidStr =
    it.PID !== undefined && it.PID !== null ? String(it.PID) : "";
  if (!pidStr) continue;

  const extra = byPID[pidStr];
  const p = points[pidStr] || it;

  if (extra) {
    p.latestRead = extra.latestRead || p.latestRead || null;
    p.hasValue = extra.value;
    it.latestRead = p.latestRead;
    it.hasValue = p.hasValue;
  }

  points[pidStr] = p;
}

// Save back into global.netList
controller.points = points;
inv.larmia_controller[ip] = controller;

try {
  global.set("netList", inv, STORE);
} catch (e) {
  global.set("netList", inv);
}

// 5) Build telemetry items from points
const telemetryItems = [];

for (const pidStr of Object.keys(points)) {
  const it = points[pidStr];
  if (!it) continue;
  if (!Object.prototype.hasOwnProperty.call(it, "hasValue")) continue;

  const raw = it.hasValue;
  let dataType = "String";
  if (typeof raw === "number") dataType = "Number";
  else if (typeof raw === "boolean") dataType = "Boolean";

  const label = (
    it.label ||        // from points flow
    it.Description ||  // description
    pidStr ||
    "unknown"
  ).toString();

  const unit = it.unit || null;
  const latestReadIso = it.latestRead
    ? new Date(it.latestRead).toISOString()
    : new Date().toISOString();

  const tele = {
    job_uuid: String(jobUuid),
    ip,
    pid: pidStr,
    label,
    dataType,
    value: raw,
    latestRead: latestReadIso
  };

  if (unit != null && unit !== "") tele.unit = String(unit);

  telemetryItems.push(tele);
}

// 6) Final message to IoTHub
msg.payload = {
  messageType: "telemetry",
  source: "larmia",
  ip,
  job_uuid: String(jobUuid),
  items: telemetryItems
};

return msg;

/**
 * Normalize & annotate telemetry messages (standalone).
 *
 * Responsibilities:
 *   - Round numeric values to 2 decimals
 *   - Ensure msg.payload.input is set
 *   - Default measuredValueType to inputName (if missing)
 *   - Normalize time to ISO string and mirror to payload.timestamp
 *   - Count incoming messages per input in persistent store
 */

const STORE = "persistent";

const inputName =
  (typeof msg.input === "string" && msg.input) || "unknown";

msg.payload = msg.payload || {};

// Normalize numeric value (string or number) to 2 decimals
if (msg.payload.value != null) {
  const n = Number(msg.payload.value);
  if (Number.isFinite(n)) {
    msg.payload.value = Math.round(n * 100) / 100;
  }
}

// Attach annotations (put input into payload for consistency)
msg.payload.input = inputName;
if (msg.payload.measuredValueType == null) {
  msg.payload.measuredValueType = inputName;
}

// Time: prefer incoming `time`, otherwise use now (ISO)
const toIso = (d) => new Date(d).toISOString();
if (
  typeof msg.payload.time === "string" &&
  !Number.isNaN(Date.parse(msg.payload.time))
) {
  msg.payload.time = toIso(msg.payload.time);
} else {
  msg.payload.time = toIso(Date.now());
}
msg.payload.timestamp = msg.payload.time;

// Count incoming (per input) in persistent store
const inKey = `incoming_count:${inputName}`;
let inCount = flow.get(inKey, STORE);
if (typeof inCount !== "number") inCount = 0;
flow.set(inKey, inCount + 1, STORE);

return msg;

/**
 * Count outgoing messages per input (standalone).
 *
 * Increments a persistent counter:
 *   outgoing_count:<inputName>
 */

const STORE = "persistent";

const inputName =
  (typeof msg.input === "string" && msg.input) || "unknown";

const outKey = `outgoing_count:${inputName}`;
let outCount = flow.get(outKey, STORE);
if (typeof outCount !== "number") outCount = 0;
flow.set(outKey, outCount + 1, STORE);

return msg;

/**
 * Drop: older than youngest (array-based, 2 outputs).
 *
 * Purpose:
 *   - Maintain, per scope, the latest accepted timestamp for each key
 *     (typically HASH for a point).
 *   - Drop messages that have a strictly older timestamp than the latest
 *     accepted one for that key.
 *
 * Outputs:
 *   1) PASS  – message is accepted and forwarded.
 *   2) AUDIT – message is dropped; small audit object for logging/debug.
 */

const STORE = "persistent";
const SCOPE = "per_hash"; // "per_hash" | "per_input" | "global"
const MAX_LEN = 4000;     // Max array length before compaction
const COMPACT_TO = 1500;  // Target unique key count after compaction

// --- Helpers ---------------------------------------------------------------

function parseToMs(t) {
  if (t == null) return NaN;
  if (t instanceof Date) return t.getTime();
  if (typeof t === "number") {
    if (t > 1e12) return t;        // assume ms
    if (t > 1e9) return t * 1000;  // seconds -> ms
    return t;                      // assume ms
  }
  if (typeof t === "string") {
    const n = Number(t);
    if (Number.isFinite(n)) return parseToMs(n);
    const p = Date.parse(t);
    return Number.isNaN(p) ? NaN : p;
  }
  return NaN;
}

function normIso(ms) {
  return new Date(ms).toISOString();
}

function scopeId(msg) {
  const inputName =
    (typeof msg.input === "string" && msg.input) ||
    msg?.payload?.input ||
    "unknown";

  if (SCOPE === "per_hash") return `perHash:${inputName}`;
  if (SCOPE === "per_input") return `perInput:${inputName}`;
  return "global";
}

/**
 * Resolve key from message:
 *   - Determine inputName, ip, PID
 *   - Try to resolve HASH from global.netList.larmia_controller[ip].points[PID].HASH
 *   - Fall back to a deterministic string if HASH is missing
 */
function keyFromMsg(msg) {
  const inputName =
    (typeof msg.input === "string" && msg.input) ||
    msg?.payload?.input ||
    "unknown";

  const cfg = global.get("config", STORE) || {};
  const ip = msg.ip || msg.host || cfg.host || "unknownIp";

  const pidRaw =
    msg?.payload?.PID ??
    msg?.payload?.pid ??
    msg.pid ??
    msg.topic ??
    null;

  let pid = pidRaw != null ? String(pidRaw) : null;

  let hashKey = null;

  if (ip && pid) {
    const net = global.get("netList", STORE) || {};
    const ctrl = net?.larmia_controller?.[ip];
    const point = ctrl?.points?.[pid];
    if (point && point.HASH != null) {
      hashKey = String(point.HASH);
    }
  }

  if (!hashKey) {
    const fallback =
      msg?.payload?.hash ||
      msg?.payload?.uuid ||
      msg?.payload?.id ||
      msg?.payload?.pointId ||
      pid ||
      `${inputName}:unknown`;

    hashKey = String(fallback);
  }

  return { inputName, hash: hashKey, pid };
}

function getArr(sid) {
  const k = `latestSeenArr:${sid}`;
  let arr = flow.get(k, STORE);
  if (!Array.isArray(arr)) arr = [];
  return { k, arr };
}

function latestForKey(arr, key) {
  for (let i = arr.length - 1; i >= 0; i--) {
    const row = arr[i];
    if (row && row[0] === key) return row[1];
  }
  return -Infinity;
}

function pushAndMaybeCompact(k, arr, key, ts) {
  arr.push([key, ts]);

  if (arr.length > MAX_LEN) {
    const seen = new Set();
    const compact = [];

    for (let i = arr.length - 1; i >= 0 && compact.length < COMPACT_TO; i--) {
      const row = arr[i];
      if (!row) continue;
      const u = row[0];
      if (!seen.has(u)) {
        compact.push(row);
        seen.add(u);
      }
    }
    compact.reverse();
    arr = compact;
  }

  flow.set(k, arr, STORE);
}

// --- Main ------------------------------------------------------------------

msg.payload = msg.payload || {};

let incomingMs = parseToMs(
  msg.payload.time ?? msg.payload.timestamp ?? Date.now()
);

if (!Number.isFinite(incomingMs)) {
  node.status({ text: "drop (invalid time)" });
  let c = flow.get("dropped_invalid_time", STORE);
  if (typeof c !== "number") c = 0;
  flow.set("dropped_invalid_time", c + 1, STORE);

  const audit = {
    payload: {
      outcome: "drop",
      reason: "INVALID_TIME",
      input:
        msg.input || msg?.payload?.input || "unknown"
    }
  };
  return [null, audit];
}

const iso = normIso(incomingMs);
msg.payload.time = iso;
msg.payload.timestamp = iso;

const { inputName, hash, pid } = keyFromMsg(msg);
const sid = scopeId(msg);
const { k, arr } = getArr(sid);

// Choose key depending on scope
const lookupKey =
  SCOPE === "per_hash"
    ? hash
    : SCOPE === "per_input"
    ? "__input__"
    : "__global__";

const lastMs = latestForKey(arr, lookupKey);

if (incomingMs < lastMs) {
  const lastIso = normIso(lastMs);
  const dk = `dropped_older_than_youngest:${inputName}`;
  let c = flow.get(dk, STORE);
  if (typeof c !== "number") c = 0;
  flow.set(dk, c + 1, STORE);

  node.status({ text: `drop < ${lastIso}` });
  const audit = {
    payload: {
      outcome: "drop",
      reason: "OLDER_THAN_YOUNGEST",
      incomingIso: iso,
      lastAcceptedIso: lastIso,
      input: inputName,
      scope: SCOPE,
      key: lookupKey,
      hash,
      pid
    }
  };
  return [null, audit];
}

// Update latest time
pushAndMaybeCompact(k, arr, lookupKey, incomingMs);

let a = flow.get(`accepted_count:${inputName}`, STORE);
if (typeof a !== "number") a = 0;
flow.set(`accepted_count:${inputName}`, a + 1, STORE);

node.status({ text: "ok (new or same time)" });

return [msg, null];

/**
 * Filter: change / keepalive based on HASH (standalone).
 *
 * Purpose:
 *   - Forward messages when the value for a given point (HASH) changes.
 *   - Forward a keepalive if no change has been sent within TIMEOUT.
 *
 * Identity:
 *   - Points are identified by HASH from:
 *       global.netList.larmia_controller[ip].points[PID].HASH
 *   - A deterministic fallback key is used if HASH is not available.
 */

const TIMEOUT = 60 * 60 * 1000; // Keepalive interval (ms)
const STORE = "persistent";

// --- Helper ----------------------------------------------------------------

function keyFromMsg(msg) {
  const inputName =
    (typeof msg.input === "string" && msg.input) ||
    msg?.payload?.input ||
    "unknown";

  const cfg = global.get("config", STORE) || {};
  const ip = cfg.host || msg.ip || msg.host || "unknownIp";

  const pidRaw =
    msg?.payload?.PID ??
    msg?.payload?.pid ??
    msg.pid ??
    msg.topic ??
    null;

  const pid = pidRaw != null ? String(pidRaw) : null;

  let hashKey = null;

  // Try to read HASH from netList.larmia_controller[ip].points[PID].HASH
  if (ip && pid) {
    const net = global.get("netList", STORE) || {};
    const ctrl = net?.larmia_controller?.[ip];
    const point = ctrl?.points?.[pid];
    if (point && point.HASH != null) {
      hashKey = String(point.HASH);
    }
  }

  // Fallback if HASH is missing so the node still behaves deterministically
  if (!hashKey) {
    const fallback =
      msg?.payload?.hash ||
      msg?.payload?.uuid ||
      msg?.payload?.id ||
      msg?.payload?.pointId ||
      pid ||
      `${inputName}:unknown`;

    hashKey = String(fallback);
  }

  return { inputName, hash: hashKey, pid };
}

// --- Main ------------------------------------------------------------------

msg.payload = msg.payload || {};

const { inputName, hash, pid } = keyFromMsg(msg);

// Write back hash/pid so they are visible downstream
msg.payload.hash = hash;
if (pid != null && msg.payload.pid == null && msg.payload.PID == null) {
  msg.payload.pid = pid;
}

// Load store (per inputName)
let store = flow.get("valueStore", STORE) || {};
if (!store[inputName]) store[inputName] = {};
const ns = store[inputName];

// Change/keepalive logic based on HASH
const newValue = msg.payload.value;
const now = Date.now();

let entry = ns[hash] || {
  lastValue: undefined,
  lastSent: 0
};

let shouldSend = false;

// Value changed → send immediately
if (newValue !== entry.lastValue) {
  entry.lastValue = newValue;
  entry.lastSent = now;
  shouldSend = true;

// No change, but timeout passed → send keepalive
} else if (now - entry.lastSent >= TIMEOUT) {
  entry.lastSent = now;
  shouldSend = true;
}

// Save state
ns[hash] = entry;
store[inputName] = ns;
flow.set("valueStore", store, STORE);

return shouldSend ? msg : null;

// Poll Scheduler (styr via global.config.pollingInterval)
// - Läser global.get('config','persistent').pollingInterval (ms eller s)
// - Start/stop/reload via msg.control: "start" | "stop" | "reload"
// - Skickar ett tick: { topic: "poll", payload: Date.now() } varje intervall

const STORE = "persistent";
const cfg = global.get("config", STORE) || {};
let ms = Number(cfg.pollingInterval);

// Tillåt att man råkar ange sekunder
if (Number.isFinite(ms) && ms > 0 && ms < 10_000) ms = ms * 1000;
// Fallback
if (!Number.isFinite(ms) || ms <= 0) ms = 60_000; // 60s default

let timer = context.get("pollTimer");

function startTimer() {
  if (timer) clearInterval(timer);
  timer = setInterval(() => {
    node.send({ topic: "poll", payload: Date.now() });
  }, ms);
  context.set("pollTimer", timer);
  node.status({ fill: "green", shape: "dot", text: `polling ${ms} ms` });
}

function stopTimer() {
  if (timer) { clearInterval(timer); timer = null; }
  context.set("pollTimer", null);
  node.status({ fill: "grey", shape: "ring", text: "stopped" });
}

const cmd = (msg.control || "").toLowerCase();
if (cmd === "stop")  { stopTimer(); return null; }
if (cmd === "start") { startTimer(); return null; }
if (cmd === "reload"){ startTimer(); return null; }

// Autostarta om inget kommandot skickas
if (!timer) startTimer();

// Vi producerar själv tickar; inkommande meddelanden släpps igenom om man vill trigga manuellt.
return null;
